<#
  90-161.Z Deployer, round bundle: Round R13: rights probe flow delivered and guided by the Deployer; seal prep searches all Inbox folders and Junk E-mail; site setup r2 (seals library fix, waits for the probe result); clearer log text.
  GENERATED by scripts/build_paste_bundles.py from scripts/paste_bundles.json; do not edit.
  How to run: open Windows PowerShell ISE, File > New, paste all of this text into the script pane, press F5.
  The 90-161.Z Deployer window opens: press Enter (or Run); it uses your Windows profile folder. It writes the files below into the task folders under
  C:\Users\<DODID>\OneDrive - United States Air Force\90-161.Z (replacing older copies), runs the steps,
  and saves its results in Rounds\R13, then opens an Outlook draft with them (never sent). No download, no admin rights.
#>
$buildId = 'd47192f0'
$goUrl = 'https://raw.githubusercontent.com/rhope-ops/90-161.Z/main/go.md'
$round = 'R13'
$usersRoot = 'C:\Users'
$files = @()
$files += @{ Dir = 'T01'; Name = 'Publication.Common.ps1'; Kind = 'text'; Sha = '3ff358dbcad2'; Data = @'
# 90-161.Z shared functions, dot-sourced by Test-Publication.ps1 and New-Publication.ps1.
# Windows PowerShell 5.1 and pwsh 7. No external modules.
# Fixed statements are verbatim DAFMAN 90-161 text; paragraph numbers are given with each.

$script:Stmt = @{
  # 4.5.5.8 (records management statement)
  Records    = 'Ensure all records generated as a result of processes prescribed in this publication adhere to Air Force Instruction (AFI) 33-322, {i}Records Management and Information Governance Program{/i}, and are disposed in accordance with the Air Force Records Disposition Schedule, which is located in the Air Force Records Information Management System.'
  # 4.5.5.9 (recommending changes statement, example)
  Changes    = 'Refer recommended changes and questions about this publication to the office of primary responsibility (OPR) using the DAF Form 847, {i}Recommendation for Change of Product{/i}; route DAF Forms 847 from the field through the appropriate functional chain of command.'
  # Table 4.5 item 2 / item 3 (4.5.5.10.1)
  SupplementMay    = 'This publication may be supplemented at any level, but all supplements must be routed to the OPR of this publication for coordination prior to certification and approval.'
  SupplementMayNot = 'This publication may not be supplemented or further implemented or extended.'
  # 4.5.5.11 (waiver authority statement, example)
  Waiver     = 'The authorities to waive wing, unit, or delta level requirements in this publication are identified with a tier (' + [char]0x201C + 'T-0, T-1, T-2, T-3' + [char]0x201D + ') number following the compliance statement. Submit requests for waivers through the chain of command to the appropriate tier waiver approval authority, or alternately, to the publication OPR for non-tiered compliance items.'
  # 4.5.5.4
  Copyright  = 'This publication contains copyrighted material.'
  # 4.5.5.5
  Paperwork  = 'This publication is subject to the Paperwork Reduction Act of 1995.'
  # 4.5.5.12 (must be the last sentence)
  TradeNames = 'The use of the name or mark of any specific manufacturer, commercial product, commodity, or service in this publication does not imply endorsement by the Department of the Air Force.'
}

function Get-PartValue($Obj, [string]$Name) {
  if ($null -eq $Obj) { return $null }
  $p = $Obj.PSObject.Properties[$Name]
  if ($null -eq $p) { return $null }
  return $p.Value
}

function Get-OpeningParagraph($Pub) {
  # Returns the opening paragraph (4.5.5). Uses "openingParts" when present (fixed text from code,
  # slots from content), else the free-text "opening" field. Order follows 4.5.5.1-4.5.5.12.
  $parts = Get-PartValue $Pub 'openingParts'
  if ($null -eq $parts) { return [string](Get-PartValue $Pub 'opening') }
  $s = New-Object System.Collections.Generic.List[string]
  $ante = [string](Get-PartValue $parts 'antecedent')
  if ($ante) { $s.Add('This publication implements ' + $ante.TrimEnd('.') + '.') }                 # 4.5.5.1
  $purpose = [string](Get-PartValue $parts 'purpose')
  if ($purpose) { $s.Add($purpose) }                                                                  # 4.5.5 (what it covers)
  $appl = [string](Get-PartValue $parts 'applicability')
  if ($appl) { $s.Add($appl) }                                                                        # 4.5.5.2
  $pa = Get-PartValue $parts 'privacyAct'
  if ($null -ne $pa) {                                                                                # 4.5.5.3
    $s.Add('This publication requires the collection and or maintenance of information protected by the Privacy Act of 1974 authorized by ' + ([string](Get-PartValue $pa 'authority')).TrimEnd('.', ' ') + '. The applicable System of Record Notice(s) (SORN) ' + ([string](Get-PartValue $pa 'sorn')).TrimEnd('.', ' ') + ' is (are) available at: http://dpclo.defense.gov/Privacy/SORNs.aspx.')
  }
  if ([bool](Get-PartValue $parts 'copyright')) { $s.Add($script:Stmt.Copyright) }                    # 4.5.5.4
  if ([bool](Get-PartValue $parts 'paperworkReduction')) { $s.Add($script:Stmt.Paperwork) }          # 4.5.5.5
  $pun = [string](Get-PartValue $parts 'punitiveScope')
  if ($pun) {                                                                                         # 4.5.5.6
    $s.Add('Failure to obey this ' + $pun + ' constitutes a violation of Article 92(1), UCMJ' + [char]0x2014 + 'failure to obey lawful order or regulation. Article 92(1) of the UCMJ does not apply to members of the ANG while in Title 32 status (that is, activated for state duty under state command), but ANG members may be subject to an equivalent article under a state military justice code.')
  }
  $stat = [string](Get-PartValue $parts 'statutory')
  if ($stat) { $s.Add($stat) }                                                                        # 4.5.5.7
  $s.Add($script:Stmt.Records)                                                                        # 4.5.5.8
  $s.Add($script:Stmt.Changes)                                                                        # 4.5.5.9
  $sup = [string](Get-PartValue $parts 'supplement')
  if ($sup -ceq 'mayNot') { $s.Add($script:Stmt.SupplementMayNot) }
  elseif ($sup -ceq 'may') { $s.Add($script:Stmt.SupplementMay) }
  else { throw "openingParts.supplement must be 'may' or 'mayNot' (4.5.5.10.1); found '$sup'" }   # 4.5.5.10
  $s.Add($script:Stmt.Waiver)                                                                         # 4.5.5.11
  if ([bool](Get-PartValue $parts 'tradeNames')) { $s.Add($script:Stmt.TradeNames) }                 # 4.5.5.12, last
  return ($s -join ' ')
}

$script:NoBreakAbbrev = @('e.g.', 'i.e.', 'Mr.', 'Mrs.', 'Ms.', 'Dr.', 'No.', 'Nos.', 'U.S.', 'St.', 'Jr.', 'Sr.', 'vs.', 'para.', 'Vol.', 'Fig.', 'Col.', 'Lt.', 'Gen.', 'Brig.', 'Maj.', 'Capt.', 'Sgt.')

function ConvertTo-TwoSpaceSentence([string]$Text) {
  # L-004: two spaces before each new sentence (measured in DAFMAN 90-161: 6.55 pt vs 3.14 pt word gap).
  if (-not $Text) { return $Text }
  $rx = [regex]('(?<end>\(T-[0-3]\)|[.?!][)"' + [char]0x201D + ']?(?:\{/[ib]\})?)(?<ws>[ ]+)(?=[A-Z0-9"(' + [char]0x201C + '{])')
  return $rx.Replace($Text, {
      param($m)
      $before = $Text.Substring(0, $m.Index + $m.Groups['end'].Length)
      foreach ($a in $script:NoBreakAbbrev) { if ($before -cmatch ('(^|[\s(])' + [regex]::Escape($a) + '$')) { return $m.Value } }
      if ($before -cmatch '(^|\s)[A-Z]\.$') { return $m.Value }              # initials, e.g. "Kimber L. Nettis"
      if ($Text.Substring($m.Index + $m.Length) -match '^\(T-[0-3]\)') { return $m.Groups['end'].Value + ' ' }   # one space before a tier number (measured: 3.08 pt, n=109)
      return $m.Groups['end'].Value + '  '
    })
}
'@ }
$files += @{ Dir = 'T01'; Name = 'Test-Publication.ps1'; Kind = 'text'; Sha = '4412325edb12'; Data = @'
<#
.SYNOPSIS
  90-161.Z validator (layer L3). Checks a publication content file (JSON, schemas/publication.schema.json)
  against the rules in docs/format-rules.md. Read-only. Runs on Windows PowerShell 5.1 and pwsh 7.

.OUTPUTS
  One line per finding: "FAIL <rule> <where>: <message>" or "WARN <rule> <where>: <message>".
  Last line: "VALIDATE fails=<n> warns=<m>". Exit code 1 when fails > 0.
#>
[CmdletBinding()]
param(
  [Parameter(Mandatory = $true)][string]$Path
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$common = Join-Path $PSScriptRoot 'Publication.Common.ps1'
if (-not (Test-Path -LiteralPath $common)) { throw 'Publication.Common.ps1 is missing. Download it into the same folder as this script.' }
. $common

$script:Findings = New-Object System.Collections.Generic.List[object]
function Add-Finding([string]$Level, [string]$Rule, [string]$Where, [string]$Message) {
  $script:Findings.Add([pscustomobject]@{ Level = $Level; Rule = $Rule; Where = $Where; Message = $Message })
}
function Get-Prop($Obj, [string]$Name) {
  if ($null -eq $Obj) { return $null }
  $p = $Obj.PSObject.Properties[$Name]
  if ($null -eq $p) { return $null }
  return $p.Value
}
function Get-PlainText([string]$Text) {
  if ($null -eq $Text) { return '' }
  return ($Text -replace '\{/?[ib]\}', '')
}
function Get-Sentence([string]$Text) {
  $plain = (Get-PlainText $Text).Trim()
  if ($plain -eq '') { return @() }
  # Split after . ? ! when followed by space and a capital letter or quote; keep tier markers with their sentence.
  return @([regex]::Split($plain, '(?<=[.?!])\s+(?=[A-Z"])') | Where-Object { $_.Trim() -ne '' })
}

$months = 'January|February|March|April|May|June|July|August|September|October|November|December'
$allText = New-Object System.Collections.Generic.List[string]
$locText = New-Object System.Collections.Generic.List[object]   # @(location, text) for the Attachment 1 report

# ---------- load ----------
try {
  $raw = Get-Content -LiteralPath $Path -Raw -Encoding UTF8
  $pub = $raw | ConvertFrom-Json
} catch {
  Write-Output ("FAIL SCHEMA file: cannot read JSON: " + $_.Exception.Message)
  Write-Output 'VALIDATE fails=1 warns=0'
  exit 1
}

$meta = Get-Prop $pub 'meta'
if ($null -eq $meta) { Add-Finding 'FAIL' 'SCHEMA' 'meta' 'meta object is missing' ; $meta = [pscustomobject]@{} }
# X-001: the extraction prompt writes [[PFM: question]] where the draft lacks a value; the build stops until the PFM replaces it.
foreach ($ph in [regex]::Matches($raw, '\[\[PFM:[^\]]*\]\]')) { Add-Finding 'FAIL' 'X-001' 'placeholder' ($ph.Value + ' must be replaced before the build') }

foreach ($f in 'action', 'directive', 'byOrderOf', 'issuerLine', 'typeAndNumber', 'designator', 'date', 'seriesTitle', 'title', 'accessibility', 'releasability', 'opr', 'certifiedBy', 'certifiedByName') {
  $v = Get-Prop $meta $f
  if ($null -eq $v -or ($v -is [string] -and $v.Trim() -eq '')) { Add-Finding 'FAIL' 'SCHEMA' "meta.$f" 'required field is missing or empty' }
}

$action = [string](Get-Prop $meta 'action')
$directive = [bool](Get-Prop $meta 'directive')
$integrated = [bool](Get-Prop $meta 'integratedSupplement')

if ($action -and $action -notin @('new', 'rewrite', 'ic', 'ac')) { Add-Finding 'FAIL' 'SCHEMA' 'meta.action' "must be new, rewrite, ic or ac (found '$action')" }

# F-013 By Order line (4.5.4.1)
$bo = [string](Get-Prop $meta 'byOrderOf')
if ($bo -and $bo -notin @('SECRETARY OF THE AIR FORCE', 'COMMANDER', 'CHIEF, NATIONAL GUARD BUREAU')) {
  Add-Finding 'FAIL' 'F-013' 'meta.byOrderOf' 'must be SECRETARY OF THE AIR FORCE, COMMANDER or CHIEF, NATIONAL GUARD BUREAU (4.5.4.1)'
}

# Wing level (F-039, F-040): By Order of the Commander and an issuer line or By Order unit line naming a WING or DELTA.
$issuerText = ([string](Get-Prop $meta 'issuerLine') + ' ' + [string](Get-Prop $meta 'byOrderOfUnit')).ToUpper()
$wingLevel = ($bo -eq 'COMMANDER') -and ($issuerText -match '\b(WING|DELTA)\b')

# F-016 date placeholder (4.5.4.4)
$date = [string](Get-Prop $meta 'date')
if ($date -and $date -ne '(Date)' -and $date -notmatch "^\d{1,2} ($($months.ToUpper())) \d{4}$") {
  Add-Finding 'WARN' 'F-016' 'meta.date' 'drafts use "(Date)"; the publishing activity dates the publication on posting (4.5.4.4)'
}

# F-018 title (4.5.4.6)
$title = [string](Get-Prop $meta 'title')
if ($title) {
  if ($title -cne $title.ToUpper()) { Add-Finding 'FAIL' 'F-018' 'meta.title' 'title must be all capital letters (4.5.4.6)' }
  foreach ($w in 'POLICY', 'INSTRUCTION', 'GUIDANCE', 'HANDBOOK', 'PAMPHLET', 'CATALOG', 'GUIDE', 'BOOK') {
    if ($title.ToUpper() -match "\b$w\b") { Add-Finding 'FAIL' 'F-018' 'meta.title' "title must not contain '$w' (4.5.4.6.2)" }
  }
  foreach ($w in 'DEPARTMENT OF THE AIR FORCE', 'AIR FORCE', 'SPACE FORCE') {
    if ($title.ToUpper() -match "\b$w\b") { Add-Finding 'FAIL' 'F-018' 'meta.title' "title must not contain '$w' (4.5.4.6.2)"; break }
  }
}

# F-020 accessibility / releasability (4.5.4.8-9)
$seal = [string](Get-Prop $meta 'shieldImage')
if ($seal -and $seal -notmatch '[\\/]Prepared[\\/][^\\/]+\.png$') { Add-Finding 'FAIL' 'L-007a' 'meta.shieldImage' 'use a seal from the "Prepared" folder made by the Task 7 seal prep (360 x 360 px PNG)' }
foreach ($f in 'accessibility', 'releasability') {
  $v = [string](Get-Prop $meta $f)
  if ($v -match '^(ACCESSIBILITY|RELEASABILITY):') { Add-Finding 'FAIL' 'F-020' "meta.$f" 'give only the statement text; the renderer adds the bold label' }
}
$link = Get-Prop $meta 'accessibilityLink'
if ($null -ne $link) {
  $lt = [string](Get-Prop $link 'text'); $lu = [string](Get-Prop $link 'url')
  if (-not $lt -or -not ([string](Get-Prop $meta 'accessibility')).Contains($lt)) { Add-Finding 'FAIL' 'F-020' 'meta.accessibilityLink.text' 'the link text must appear word for word in meta.accessibility' }
  if ($lu -notmatch '^https://') { Add-Finding 'FAIL' 'F-020' 'meta.accessibilityLink.url' 'give the full https:// address of the wing site page' }
}

# F-021 OPR / Certified By: office symbols only, no names (4.5.4.10-11)
foreach ($f in 'opr', 'certifiedBy') {
  $v = [string](Get-Prop $meta $f)
  if ($v -cmatch '\b[A-Z][a-z]+\s+[A-Z][a-z]+\b' -or $v -cmatch '\b(Mr|Mrs|Ms|Dr|Col|Lt|Maj|Capt|SMSgt|MSgt|TSgt|SSgt|CMSgt)\.?\s') {
    Add-Finding 'FAIL' 'F-021' "meta.$f" 'use the organization or office symbol only, no names (4.5.4.10-11)'
  }
}

# F-022 supersedes (4.5.4.12)
$sup = @(Get-Prop $meta 'supersedes' | Where-Object { $null -ne $_ })
if ($sup.Count -gt 0 -and $action -ne 'rewrite') { Add-Finding 'FAIL' 'F-022' 'meta.supersedes' 'Supersedes applies only to a rewrite (4.5.4.12)' }
foreach ($s in $sup) {
  $d = [string](Get-Prop $s 'date')
  if ($d -notmatch "^\d{1,2} ($months) \d{4}$") { Add-Finding 'FAIL' 'F-022' 'meta.supersedes' "date '$d' must be 'D Month YYYY' with the month spelled out (4.5.4.12)" }
}

# F-024 / opening paragraph (4.5.5)
$parts = Get-Prop $pub 'openingParts'
if ($null -ne $parts) {
  if ([string](Get-Prop $parts 'antecedent') -notmatch '\{i\}') { Add-Finding 'FAIL' 'F-024' 'openingParts.antecedent' 'name the antecedent publication with its title in italics ({i}...{/i}) (4.5.5.1)' }
  if ([string](Get-Prop $parts 'supplement') -cnotin @('may', 'mayNot')) { Add-Finding 'FAIL' 'F-025' 'openingParts.supplement' "must be 'may' or 'mayNot' (4.5.5.10.1, Table 4.5)" }
  if (-not [string](Get-Prop $parts 'applicability')) { Add-Finding 'FAIL' 'F-025' 'openingParts.applicability' 'applicability statement is required (4.5.5.2)' }
}
try { $opening = [string](Get-OpeningParagraph $pub) } catch { $opening = ''; Add-Finding 'FAIL' 'F-025' 'openingParts' $_.Exception.Message }
if ($directive -and $opening.Trim() -eq '') { Add-Finding 'FAIL' 'F-024' 'opening' 'directive publications need an opening paragraph (4.5.5)' }
if ($opening) {
  $allText.Add($opening)
  $first = (Get-Sentence $opening | Select-Object -First 1)
  if ($first -and $opening -notmatch '\{i\}') { Add-Finding 'WARN' 'F-024' 'opening' 'first sentence should name the antecedent publication with its title in italics ({i}...{/i}) (4.5.5.1)' }
  if ($directive -and $opening -notmatch 'Ensure all records generated as a result of processes prescribed in this') {
    Add-Finding 'FAIL' 'F-025' 'opening' 'records management statement is missing (4.5.5.8)'
  }
  if ($directive -and $opening -notmatch 'DAF Form 847') { Add-Finding 'FAIL' 'F-025' 'opening' 'recommending-changes statement (DAF Form 847) is missing (4.5.5.9)' }
  if ($directive -and $opening -notmatch 'waive') { Add-Finding 'FAIL' 'F-025' 'opening' 'waiver authority statement is missing (4.5.5.11)' }
  if ($directive -and $opening -notmatch 'supplement') { Add-Finding 'WARN' 'F-025' 'opening' 'statement on whether the publication may be supplemented is missing (4.5.5.10)' }
  if ($opening -match 'does not imply endorsement' -and ((Get-Sentence $opening | Select-Object -Last 1) -notmatch 'does not imply endorsement')) {
    Add-Finding 'FAIL' 'F-025' 'opening' 'the trade name disclaimer must be the last sentence of the opening paragraph (4.5.5.12)'
  }
}

# F-026 summary of changes (4.5.6)
$soc = [string](Get-Prop $pub 'summaryOfChanges')
$socNeeded = $action -in @('rewrite', 'ic')
if ($socNeeded -and $soc.Trim() -eq '') { Add-Finding 'FAIL' 'F-026' 'summaryOfChanges' 'required for rewrites and interim changes (4.5.6)' }
if (-not $socNeeded -and $soc.Trim() -ne '') { Add-Finding 'FAIL' 'F-026' 'summaryOfChanges' 'new publications and administrative changes have no summary of changes (4.5.6)' }
if ($action -eq 'ic' -and ((Get-Sentence $soc | Select-Object -Last 1) -ne 'A margin bar (|) indicates newly revised material.')) {
  Add-Finding 'FAIL' 'F-026' 'summaryOfChanges' 'last sentence must be "A margin bar (|) indicates newly revised material." (4.5.6.2)'
}
if ($soc) { $allText.Add($soc); if (@(Get-Sentence $soc).Count -gt 4) { Add-Finding 'WARN' 'F-026' 'summaryOfChanges' 'keep it to a few sentences (4.5.6)' } }

# ---------- body ----------
$body = Get-Prop $pub 'body'
$chapters = @(Get-Prop $body 'chapters' | Where-Object { $null -ne $_ })
$flatParas = @(Get-Prop $body 'paragraphs' | Where-Object { $null -ne $_ })
if ($chapters.Count -eq 0 -and $flatParas.Count -eq 0) { Add-Finding 'FAIL' 'SCHEMA' 'body' 'body needs chapters or paragraphs' }
if ($chapters.Count -gt 0 -and $flatParas.Count -gt 0) { Add-Finding 'FAIL' 'SCHEMA' 'body' 'use chapters or paragraphs, not both' }

$script:RevisedCount = 0
function Test-Paragraph($P, [string]$Number, [int]$Parts, [bool]$TopLevel) {
  $where = "para $Number"
  if ($Parts -gt 7) { Add-Finding 'FAIL' 'F-006' $where 'more than seven paragraph levels (4.5.3.5)' }
  $t = [string](Get-Prop $P 'title')
  $x = [string](Get-Prop $P 'text')
  if ($t) { $allText.Add($t) }
  if ($x) { $allText.Add($x) }
  $extra = @(@(Get-Prop $P 'notes') + @(Get-Prop $P 'exceptions') + @(Get-Prop $P 'bullets') | Where-Object { $_ -is [string] })
  $tblObj = Get-Prop $P 'table'
  if ($null -ne $tblObj) { $extra += [string](Get-Prop $tblObj 'title'); foreach ($r in @(Get-Prop $tblObj 'rows')) { $extra += (@($r) -join ' ') } }
  $locText.Add(@($Number.TrimEnd('.'), ($t + ' ' + $x + ' ' + ($extra -join ' '))))
  if ($t -match '^\s*core content\.?\s*$') { Add-Finding 'FAIL' 'F-031' $where 'do not title a section "Core Content" (4.5.9.7)' }
  if ($TopLevel -and -not $t) { Add-Finding 'WARN' 'F-028' $where 'main paragraphs should have a bold heading (4.5.9.2)' }
  if ($t -and $t -notmatch '[.?]$') { Add-Finding 'WARN' 'F-028' $where 'headings end with a period (example "7.5. Certification of Publication as Current.") (4.5.9.2)' }
  if ($x -match '^\s*(Note|Exception)\s*:') { Add-Finding 'FAIL' 'F-037' $where 'put notes in "notes" and exceptions in "exceptions"; the renderer adds the bold label (4.6.2, 4.6.3)' }
  foreach ($n in @(Get-Prop $P 'notes') + @(Get-Prop $P 'exceptions')) {
    if ($null -ne $n) { $allText.Add([string]$n); if ([string]$n -match '^\s*(Note|Exception)\s*:') { Add-Finding 'FAIL' 'F-037' $where 'omit the "Note:" or "Exception:" label; the renderer adds it' } }
  }
  $bul = @(Get-Prop $P 'bullets' | Where-Object { $null -ne $_ })
  if ($bul.Count -gt 0) {
    if ($directive) { Add-Finding 'FAIL' 'F-029' $where 'directive publications cannot use bullets; use numbered paragraphs (4.5.9.3.1)' }
    foreach ($b in $bul) { if ($b -isnot [string]) { Add-Finding 'FAIL' 'F-029' $where 'sub-bullets are not allowed (4.5.9.3.2)' } else { $allText.Add($b) } }
  }
  if ([bool](Get-Prop $P 'revised')) { $script:RevisedCount++ }
  $tbl = Get-Prop $P 'table'
  if ($null -ne $tbl) {
    if (-not [string](Get-Prop $tbl 'title')) { Add-Finding 'FAIL' 'F-038' $where 'tables need a title (placed above the table) (4.6.4)' }
    $cols = @(Get-Prop $tbl 'columns'); $rows = @(Get-Prop $tbl 'rows')
    foreach ($r in $rows) { if (@($r).Count -ne $cols.Count) { Add-Finding 'FAIL' 'SCHEMA' $where 'table row cell count does not match the column count' } }
  }
  $fig = Get-Prop $P 'figure'
  if ($null -ne $fig -and -not [string](Get-Prop $fig 'title')) { Add-Finding 'FAIL' 'F-038' $where 'figures need a title (placed above the figure) (4.6.4)' }
  $kids = @(Get-Prop $P 'children' | Where-Object { $null -ne $_ })
  if ($kids.Count -eq 1 -and -not $integrated) { Add-Finding 'FAIL' 'F-005' $where 'a subparagraph needs at least one companion at the same level (4.5.3.4)' }
  for ($i = 0; $i -lt $kids.Count; $i++) { Test-Paragraph $kids[$i] ("$Number$($i + 1).") ($Parts + 1) $false }
}

if ($chapters.Count -gt 0) {
  for ($c = 0; $c -lt $chapters.Count; $c++) {
    $ch = $chapters[$c]; $cn = $c + 1
    $ct = [string](Get-Prop $ch 'title')
    if (-not $ct) { Add-Finding 'FAIL' 'SCHEMA' "chapter $cn" 'chapter title is missing' }
    elseif ($ct -cne $ct.ToUpper()) { Add-Finding 'FAIL' 'F-033' "chapter $cn" 'chapter titles are all capital letters (4.5.9.7.4.5)' }
    if ($ct -match '^\s*CORE CONTENT\s*$') { Add-Finding 'FAIL' 'F-031' "chapter $cn" 'do not title a section "Core Content" (4.5.9.7)' }
    $ps = @(Get-Prop $ch 'paragraphs' | Where-Object { $null -ne $_ })
    if ($ps.Count -eq 0) { Add-Finding 'FAIL' 'SCHEMA' "chapter $cn" 'chapter has no paragraphs' }
    for ($i = 0; $i -lt $ps.Count; $i++) { Test-Paragraph $ps[$i] ("$cn.$($i + 1).") 2 $true }
  }
} else {
  for ($i = 0; $i -lt $flatParas.Count; $i++) { Test-Paragraph $flatParas[$i] ("$($i + 1).") 1 $true }
}

if ($script:RevisedCount -gt 0 -and $action -ne 'ic') { Add-Finding 'WARN' 'F-026' 'body' 'margin bars ("revised") are for interim changes (4.5.6.2)' }
if ($action -eq 'ic' -and $script:RevisedCount -eq 0) { Add-Finding 'WARN' 'F-026' 'body' 'interim change has no paragraph marked "revised"' }

# F-034 signature block (4.5.10)
$sig = @(Get-Prop $pub 'signature' | Where-Object { $null -ne $_ })
if ($directive -and $sig.Count -eq 0) { Add-Finding 'FAIL' 'F-034' 'signature' 'approving official authentication block is missing (4.5.2, 4.5.10)' }

# ---------- attachments (4.5.11) ----------
$atts = @(Get-Prop $pub 'attachments' | Where-Object { $null -ne $_ })
$gloss = $null
for ($a = 0; $a -lt $atts.Count; $a++) {
  $at = $atts[$a]; $an = $a + 1
  $att = [string](Get-Prop $at 'title')
  if (-not $att) { Add-Finding 'FAIL' 'F-008' "attachment $an" 'each attachment needs a title (4.5.3.7)' }
  elseif ($att -cne $att.ToUpper()) { Add-Finding 'FAIL' 'F-033' "attachment $an" 'attachment titles are all capital letters (4.5.9.7.4.13)' }
  $g = Get-Prop $at 'glossary'
  if ($null -ne $g) {
    if ($an -ne 1) { Add-Finding 'FAIL' 'F-035' "attachment $an" 'the glossary must be Attachment 1 (4.5.11.1)' }
    if ($att -ne 'GLOSSARY OF REFERENCES AND SUPPORTING INFORMATION') { Add-Finding 'FAIL' 'F-035' 'attachment 1' 'title must be GLOSSARY OF REFERENCES AND SUPPORTING INFORMATION (4.5.11.1)' }
    $gloss = $g
  } else {
    $aps = @(Get-Prop $at 'paragraphs' | Where-Object { $null -ne $_ })
    for ($i = 0; $i -lt $aps.Count; $i++) { Test-Paragraph $aps[$i] ("A$an.$($i + 1).") 2 $true }
  }
}
$typeNum = [string](Get-Prop $meta 'typeAndNumber')
$needsGlossary = $typeNum -cmatch '\b(INSTRUCTION|MANUAL|POLICY DIRECTIVE)\b'
if ($needsGlossary -and $null -eq $gloss) { Add-Finding 'FAIL' 'F-035' 'attachments' 'Attachment 1 (glossary) is required for policy directives, instructions and manuals (4.5.11.1)' }

$abbr = @{}
$abbrKind = @{}   # term -> 'abbreviations' or 'officeSymbols'
if ($null -ne $gloss) {
  foreach ($r in @(Get-Prop $gloss 'references')) {
    if ($null -ne $r -and [string]$r -match '(https?://|www\.)') { Add-Finding 'FAIL' 'F-035' 'glossary.references' "references do not include URLs: '$r' (4.5.11.1)" }
  }
  foreach ($sec in 'abbreviations', 'officeSymbols', 'terms') {
    $items = @(Get-Prop $gloss $sec | Where-Object { $null -ne $_ })
    $names = @($items | ForEach-Object { [string](Get-Prop $_ 'term') })
    $sorted = @($names | Sort-Object)
    if (($names -join '|') -ne ($sorted -join '|')) { Add-Finding 'WARN' 'F-035' "glossary.$sec" 'list entries in alphabetical order (4.5.11.1)' }
    if ($sec -ne 'terms') { foreach ($n in $names) { $abbr[$n] = $true; $abbrKind[$n] = $sec } }
  }
}

# ---------- writing rules over all text ----------
$joined = (Get-PlainText ($allText -join "`n"))
# Cover values (OPR, Certified by, unit lines) use glossary entries too (T06 review 12 Nov 26): count them as use.
$coverText = (@(foreach ($f in 'opr', 'certifiedBy', 'byOrderOfUnit', 'issuerLine', 'title', 'typeAndNumber') { [string](Get-Prop $meta $f) }) -join "`n")
$skip = @('DAF', 'AFI', 'DAFI', 'DAFMAN', 'AFMAN', 'UCMJ', 'USC', 'DOD', 'NOTE', 'TABLE', 'A', 'I', 'II', 'III', 'IV')
foreach ($k in @($abbr.Keys)) {
  $pattern = "(?<![A-Za-z0-9/-])$([regex]::Escape($k))(?![A-Za-z0-9-])"
  $c = ([regex]::Matches($joined, $pattern)).Count
  $all = $c + ([regex]::Matches($coverText, $pattern)).Count
  if ($all -eq 0) { Add-Finding 'WARN' 'F-032' 'glossary' "'$k' is listed but not used in the text" }
  # The four-times rule is for acronyms only: not office symbols, not publication-type prefixes in references (AFI 33-322).
  elseif ($c -le 4 -and $abbrKind[$k] -eq 'abbreviations' -and $k -notin $skip) { Add-Finding 'WARN' 'F-032' 'glossary' "'$k' is used $c time(s); acronyms used four times or less should generally be spelled out (4.5.9.7.2.5)" }
}
$caps = [regex]::Matches($joined, '\b[A-Z]{2,6}\b') | ForEach-Object { $_.Value } | Sort-Object -Unique
foreach ($w in $caps) {
  if (-not $abbr.ContainsKey($w) -and $w -notin $skip -and $joined -notmatch "\($w\)") {
    Add-Finding 'WARN' 'F-032' 'text' "'$w' is not defined at first use or listed in Attachment 1 (4.5.9.7.2)"
  }
}

$pi = 0
foreach ($t in $allText) {
  $pi++
  $plain = Get-PlainText $t
  if ($plain -match '\bshall\b') { Add-Finding 'FAIL' 'W-001' "text block $pi" 'use "must", not "shall" (Table 1.1)' }
  $sent = @(Get-Sentence $t)
  if ($sent.Count -gt 7 -and $t -ne $opening) { Add-Finding 'WARN' 'W-002' "text block $pi" "paragraph has $($sent.Count) sentences; use seven or fewer (Table 1.1)" }
  foreach ($s in $sent) {
    $wc = @($s -split '\s+' | Where-Object { $_ -match '\w' -and $_ -notmatch '^\(T-[0-3]\)$' }).Count
    if ($wc -gt 20 -and $t -ne $opening) { Add-Finding 'WARN' 'W-002' "text block $pi" "sentence has $wc words; use 20 or fewer: '$($s.Substring(0, [Math]::Min(60, $s.Length)))...'" }
    # PFM 2B (2026-11-12): wing or delta statements carry no tier unless the waiver authority is above the wing, so F-039 is off there.
    # The fixed summary-of-changes sentence ("... revised and must be completely reviewed") is not a compliance statement (T06 review 12 Nov 26).
    $fixedSoc = $s -match '^\s*This (document|publication) has been (substantially )?revised and (must|should) be completely reviewed'
    if (-not $wingLevel -and -not $fixedSoc -and $s -match '\b(will|must)\b' -and $s -notmatch '\(T-[0-3]\)' -and $t -ne $opening) {
      Add-Finding 'WARN' 'F-039' "text block $pi" "possible compliance statement without a tier number: '$($s.Substring(0, [Math]::Min(60, $s.Length)))...' (4.6.5)"
    }
  }
  foreach ($m in [regex]::Matches($plain, '\b[A-Z]{7,}\b')) { Add-Finding 'WARN' 'W-003' "text block $pi" "'$($m.Value)': do not use capital letters for emphasis (Table 1.1)" }
  $opens = ([regex]::Matches($t, '\{([ib])\}')).Count; $closes = ([regex]::Matches($t, '\{/([ib])\}')).Count
  if ($opens -ne $closes) { Add-Finding 'FAIL' 'SCHEMA' "text block $pi" 'unbalanced {i}/{b} markup' }
}

# ---------- Attachment 1 tracking report (4.5.11.1): what the text uses vs what the glossary lists ----------
$listedRefs = @(); $listedForms = @()
if ($null -ne $gloss) {
  $listedRefs = @(Get-Prop $gloss 'references' | Where-Object { $null -ne $_ } | ForEach-Object { Get-PlainText ([string]$_) })
  $listedForms = @((@(Get-Prop $gloss 'prescribedForms') + @(Get-Prop $gloss 'adoptedForms')) | Where-Object { $null -ne $_ } | ForEach-Object { Get-PlainText ([string]$_) })
}
$locText.Insert(0, @('opening', $opening))
if ($soc) { $locText.Insert(1, @('summaryOfChanges', $soc)) }
$seen = @{}
foreach ($lt in $locText) {
  $where = [string]$lt[0]; $plain = Get-PlainText ([string]$lt[1])
  foreach ($m in [regex]::Matches($plain, '\(([A-Z][A-Z0-9/&-]*[A-Z][A-Za-z0-9/&-]*)\)')) {
    $k = 'ACR ' + $m.Groups[1].Value
    if ($m.Groups[1].Value -match '^T-[0-3]$') { continue }
    if (-not $seen.ContainsKey($k)) { $seen[$k] = $where; $listed = $abbr.ContainsKey($m.Groups[1].Value)
      Write-Output ("ATT1 acronym {0} first={1} listed={2}" -f $m.Groups[1].Value, $where, $(if ($listed) { 'yes' } else { 'no' })) }
  }
  foreach ($m in [regex]::Matches($plain, '\b((?:DAF|AF|DD|SF|OF|[A-Z0-9]{2,8}) Form [0-9][0-9A-Z-]*)')) {
    $k = 'FORM ' + $m.Groups[1].Value
    if (-not $seen.ContainsKey($k)) { $seen[$k] = $where; $fm = $m.Groups[1].Value; $listed = @($listedForms | Where-Object { $_ -match ('^' + [regex]::Escape($fm) + '([^0-9A-Za-z]|$)') }).Count -gt 0
      Write-Output ("ATT1 form {0} first={1} listed={2}" -f $m.Groups[1].Value, $where, $(if ($listed) { 'yes' } else { 'no' }))
      if (-not $listed) { Add-Finding 'WARN' 'F-035' $where "form '$($m.Groups[1].Value)' is used but not listed in Attachment 1 (4.5.11.1)" } }
  }
  foreach ($m in [regex]::Matches($plain, '\b(DoD[DIM]?|DAF(?:PD|I|MAN|PAM|H)|AF(?:PD|I|MAN|PAM|H)|SPF(?:PD|I|MAN))\)?\s?([0-9]{1,2}-[0-9]{2,4}(?:V[0-9]+)?)')) {
    $ref = $m.Groups[1].Value + ' ' + $m.Groups[2].Value
    $k = 'REF ' + ($ref -replace '\s', '')
    if (-not $seen.ContainsKey($k)) { $seen[$k] = $where
      $listed = @($listedRefs | Where-Object { ($_ -replace '\s', '') -like (($ref -replace '\s', '') + '*') }).Count -gt 0
      Write-Output ("ATT1 reference {0} first={1} listed={2}" -f $ref, $where, $(if ($listed) { 'yes' } else { 'no' }))
      if (-not $listed) { Add-Finding 'WARN' 'F-035' $where "reference '$ref' is cited but not listed in Attachment 1 (4.5.11.1)" } }
  }
}

# ---------- F-040 tier at the issuer's own level (Attachment 10 note 4) ----------
# The wing or delta/CC who approved a wing or delta publication is already the default waiver authority,
# so (T-3) in that publication is redundant. Wing level = By Order of the Commander and an issuer line
# (or By Order unit line) that names a WING or DELTA ($wingLevel, set after F-013).
if ($wingLevel) {
  foreach ($lt in $locText) {
    $where = [string]$lt[0]; $plain = Get-PlainText ([string]$lt[1])
    foreach ($m in [regex]::Matches($plain, '\(\s*T\s*[-\u2013]\s*3\s*\)')) {
      $start = [Math]::Max(0, $m.Index - 50)
      Add-Finding 'WARN' 'F-040' $where ("(T-3) is redundant in a wing or delta publication; the wing or delta/CC who approved it is already the waiver authority: '..." + $plain.Substring($start, $m.Index + $m.Length - $start).Trim() + "' (Attachment 10 note 4)")
    }
  }
}

# ---------- report ----------
$fails = @($script:Findings | Where-Object { $_.Level -eq 'FAIL' }).Count
$warns = @($script:Findings | Where-Object { $_.Level -eq 'WARN' }).Count
foreach ($f in $script:Findings) { Write-Output ('{0} {1} {2}: {3}' -f $f.Level, $f.Rule, $f.Where, $f.Message) }
Write-Output "VALIDATE fails=$fails warns=$warns"
if ($fails -gt 0) { exit 1 }
exit 0
'@ }
$files += @{ Dir = 'T01'; Name = 'New-Publication.ps1'; Kind = 'text'; Sha = '32fc2efaa7dc'; Data = @'
<#
.SYNOPSIS
  90-161.Z renderer (layer L2). Builds a camera-ready Word file that looks like DAFMAN 90-161
  from a publication content file (JSON, schemas/publication.schema.json).

.DESCRIPTION
  Format comes only from this code. Values are from DAFMAN 90-161 (rule IDs in docs/format-rules.md)
  or measured from ref/dafman90-161.pdf (layout IDs L-xxx in docs/format-rules.md).
  The validator (Test-Publication.ps1) runs first; the renderer stops if it reports any FAIL.
  Needs: Windows PowerShell 5.1 and Microsoft Word 16 (COM). Nothing else.

.EXAMPLE
  .\New-Publication.ps1 -Path .\mypub.json -Mode draft
  .\New-Publication.ps1 -Path .\mypub.json -Mode final -Pdf
#>
[CmdletBinding()]
param(
  [Parameter(Mandatory = $true)][string]$Path,
  [ValidateSet('draft', 'final')][string]$Mode = 'draft',
  [string]$OutDir,
  [switch]$Pdf
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$common = Join-Path $PSScriptRoot 'Publication.Common.ps1'
if (-not (Test-Path -LiteralPath $common)) { throw 'Publication.Common.ps1 is missing. Download it into the same folder as this script.' }
. $common

# ---------------- constants (rule / layout IDs in docs/format-rules.md) ----------------
$PT = 72                       # points per inch
$FontName = 'Times New Roman'  # F-001 (4.5.3.1)
$FontSize = 12                 # F-001
$Margin = 1.0 * $PT            # F-001: one-inch margins
$HeaderDist = 0.5 * $PT        # L-001: running header top at 0.507 in
$IndentStep = 0.25 * $PT       # L-002: each paragraph level indents 0.25 in
$SpaceAfter = 6                # L-003: 6 pt between paragraphs
$Gap = '  '                    # L-004: two spaces after paragraph numbers, headings, and in the running header
$LabelTab = 1.5 * $PT          # L-005: ACCESSIBILITY/RELEASABILITY text starts 1.5 in from the margin
$SigIndent = 3.0 * $PT         # L-006: signature block starts 4.0 in from the page edge
$ShieldWidth = 1.2 * $PT       # L-007: seal/shield box 1.20 in square
$SealBefore = 6.3              # L-007: seal top at 1.47 in; assumes 2 header lines (BY ORDER OF + unit), which end at 1.383 in (gov T07 r1: seal sat 0.087 in high)
$SealPx = 360                  # L-007a: prepared seals are 360 x 360 px PNG (Task 7 seal prep), emblem centered (PFM 2A)
$RuleWidth = 6                 # L-008: cover rules 0.75-0.80 pt measured on 7 covers (wdLineWidth075pt)
# L-008a: cover spacing measured on DAFMAN 90-161 page 1 (baseline/rule gaps, inches): title->compliance 0.417,
# compliance->rule 0.182, rule->ACCESSIBILITY 0.285, RELEASABILITY->rule 0.264, rule->OPR 0.394,
# Supersedes->rule 0.415, rule->opening 0.369. Values below reproduce them within 0.02 in.
$ComplianceBefore = 16         # L-010e / L-008a: space before the compliance line (pt)
$ComplianceRuleDist = 11       # L-008a: text-to-rule distance under the compliance line (pt)
$ComplianceAfter = 9           # L-008a: rule to ACCESSIBILITY
$ReleaseRuleDist = 16          # L-008a: text-to-rule distance under RELEASABILITY (pt)
$ReleaseAfter = 16             # L-008a: rule to OPR line
$BlockRuleBefore = 12.5        # L-008a: Supersedes/Pages line to the third rule
$GroupBlankLine = 12           # L-010c: blank line between right-column groups, exactly 12 pt (group pitch 0.358 in on DAFMAN 90-161)
$TocFontSize = 11              # L-012: TOC on DAFMAN 90-161 page 2: 11 pt; chapter and attachment lines bold (4.5.9.7.4.2), paragraph lines not bold
$TocLine = 14.5                # L-012: 0.202 in between lines of one entry (exactly 14.5 pt)
$TocAfter = 5                  # L-012: 0.272 in between entries
$TocHang = 1.0 * $PT           # L-012: entry text and wrapped lines at 2.00 in (1.00 in from the margin)
$TocNumber = 0.5 * $PT         # L-012: paragraph number at 1.50 in
$OprTab = 0.5 * $PT            # L-010f: office symbol 0.50 in after "OPR:"
$SupTab = 1.0 * $PT            # L-010g: Supersedes value 1.00 in after the label, wraps under itself
$OprLeftCol = 4.0 * $PT        # L-010g/h: Supersedes value wraps before 5.0 in; Certified by / Pages right-aligned at 7.50 in
$TextWidth = 6.5 * $PT
$DraftMark = "DRAFT$([char]0x2014)NOT FOR IMPLEMENTATION OR COMPLIANCE"   # F-010 (4.5.1)
$EmDash = [char]0x2014

# Word enums
$wdAlignLeft = 0; $wdAlignCenter = 1; $wdAlignRight = 2; $wdAlignJustify = 3
$wdBorderBottom = -3; $wdBorderLeft = -2
$wdHeaderPrimary = 1; $wdHeaderFirst = 2; $wdHeaderEven = 3
$wdFieldPage = 33; $wdStatisticPages = 2
$wdFormatDocx = 16; $wdFormatPdf = 17
$wdAlignTabRight = 2; $wdStory = 6; $wdPageBreak = 7
$wdLineSpaceExactly = 4; $wdStyleTOC1 = -20; $wdStyleTOC2 = -21

function ConvertTo-WordBool([bool]$Value) { if ($Value) { return -1 } return 0 }   # Word True = -1
function Get-Prop($Obj, [string]$Name) {
  if ($null -eq $Obj) { return $null }
  $p = $Obj.PSObject.Properties[$Name]
  if ($null -eq $p) { return $null }
  return $p.Value
}

# ---------------- validate first (L3) ----------------
$validator = Join-Path $PSScriptRoot 'Test-Publication.ps1'
$report = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $validator -Path $Path
$validExit = $LASTEXITCODE
$report | ForEach-Object { Write-Output $_ }
if ($validExit -ne 0) { throw 'Validator reported FAIL findings. Fix the content file, then run again. No document was built.' }

$pub = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
$meta = Get-Prop $pub 'meta'
$directive = [bool](Get-Prop $meta 'directive')
$designator = [string](Get-Prop $meta 'designator')
$dateText = [string](Get-Prop $meta 'date')
if (-not $OutDir) { $OutDir = Split-Path -Parent (Resolve-Path -LiteralPath $Path).Path }
if (-not (Test-Path -LiteralPath $OutDir)) { New-Item -ItemType Directory -Path $OutDir | Out-Null }
$OutDir = (Resolve-Path -LiteralPath $OutDir).Path   # Word needs an absolute path
$suffix = ''
if ($Mode -eq 'draft') { $suffix = '_DRAFT' }
$outDocx = Join-Path $OutDir ($designator + $suffix + '.docx')   # S-001: file name without spaces (3.8.2)

# ---------------- seal check (L-007a), before Word starts ----------------
$shield = [string](Get-Prop $meta 'shieldImage')
if ($shield) {
  if (-not (Test-Path -LiteralPath $shield -PathType Leaf)) { throw ('SEAL not found (L-007a): ' + $shield) }
  Add-Type -AssemblyName System.Drawing
  $probe = [System.Drawing.Image]::FromFile((Resolve-Path -LiteralPath $shield).Path)
  try {
    $sealOk = ($probe.Width -eq $SealPx -and $probe.Height -eq $SealPx -and $probe.RawFormat.Guid -eq [System.Drawing.Imaging.ImageFormat]::Png.Guid)
  } finally { $probe.Dispose() }
  if (-not $sealOk) { throw ('SEAL not prepared (L-007a): use the PNG in the "Prepared" folder made by the Task 7 seal prep (' + $SealPx + ' x ' + $SealPx + ' px).') }
}

# ---------------- Word helpers ----------------
$word = $null; $doc = $null
# T06/T07 gov runs 2026-11-11: Word stopped with "Specified cast is not valid" and no line number.
# Each layout step added after r3 now runs in Use-Format: a failure prints FORMAT-FAIL with the rule and
# the script line, the build goes on (so the PDF still exists for measurement), and the exit code is 3.
$script:formatFails = 0
function Use-Format([string]$Rule, [scriptblock]$Do) {
  try { & $Do } catch {
    $script:formatFails++
    Write-Output ('FORMAT-FAIL ' + $Rule + ' line ' + $_.InvocationInfo.ScriptLineNumber + ': ' + $_.Exception.Message)
  }
}
function Invoke-ComSet($Obj, [string]$Name, $Value) {
  # Late-bound set: bypasses the PowerShell COM adapter's type conversion.
  [void]$Obj.GetType().InvokeMember($Name, [Reflection.BindingFlags]::SetProperty, $null, $Obj, @($Value))
}
function Invoke-ParaFormat($Style, $Values) {
  # Sets $Values (name -> value) on $Style.ParagraphFormat; returns the route that worked. Throws if all 3 fail.
  $errs = @()
  $k = ''
  try { $pf = $Style.ParagraphFormat; foreach ($k in $Values.Keys) { $pf.$k = $Values[$k] }; return 'direct' } catch { $errs += ('direct[' + $k + ']: ' + $_.Exception.Message) }
  try {
    $copy = $Style.ParagraphFormat.Duplicate
    foreach ($k in $Values.Keys) { $copy.$k = $Values[$k] }
    $Style.ParagraphFormat = $copy
    return 'copy'
  } catch { $errs += ('copy[' + $k + ']: ' + $_.Exception.Message) }
  try {
    $pf = $Style.GetType().InvokeMember('ParagraphFormat', [Reflection.BindingFlags]::GetProperty, $null, $Style, $null)
    foreach ($k in $Values.Keys) { $v = $Values[$k]; if ($v -is [double]) { $v = [single]$v }; Invoke-ComSet $pf $k $v }   # Word float properties
    return 'invoke'
  } catch { $errs += ('invoke[' + $k + ']: ' + $_.Exception.Message) }
  throw ($errs -join ' | ')
}
function Format-Para([int]$Align = 3, [double]$Left = 0, [double]$First = 0, [double]$After = $SpaceAfter, [bool]$KeepNext = $false) {
  $pf = $script:sel.ParagraphFormat
  $pf.Alignment = $Align
  $pf.LeftIndent = $Left
  $pf.FirstLineIndent = $First
  $pf.SpaceBefore = 0
  $pf.SpaceAfter = $After
  $pf.LineSpacingRule = 0   # single
  $pf.KeepWithNext = ConvertTo-WordBool $KeepNext
  $pf.TabStops.ClearAll()
  $pf.Borders.Enable = 0
  $script:sel.Font.Bold = 0; $script:sel.Font.Italic = 0
  $script:sel.Font.Name = $FontName; $script:sel.Font.Size = $FontSize
}
function Write-Rich([string]$Text, [bool]$Bold = $false, [bool]$Italic = $false) {
  # Inline markup: {i}..{/i}, {b}..{/b}. Tier numbers "(T-0..3)" are bold (F-039, 4.5.9.7.4.12).
  # Two spaces before each new sentence (L-004).
  if ($null -eq $Text) { return }
  $Text = ConvertTo-TwoSpaceSentence $Text
  $tokens = [regex]::Split($Text, '(\{/?[ib]\}|\(T-[0-3]\))')
  $b = $Bold; $i = $Italic
  foreach ($t in $tokens) {
    switch -regex ($t) {
      '^\{i\}$' { $i = $true; continue }
      '^\{/i\}$' { $i = $Italic; continue }
      '^\{b\}$' { $b = $true; continue }
      '^\{/b\}$' { $b = $Bold; continue }
      '^\(T-[0-3]\)$' {
        # Word nonbreaking hyphen (character 30): "(T-3)" never splits across two lines (T01 r3 result, 2.2).
        $script:sel.Font.Bold = -1; $script:sel.Font.Italic = (ConvertTo-WordBool $i)
        $nb = $t.Replace('-', [string][char]30)
        try { $script:sel.TypeText([string]$nb) } catch {
          $script:formatFails++
          Write-Output ('FORMAT-FAIL F-039 nonbreaking hyphen line ' + $_.InvocationInfo.ScriptLineNumber + ': ' + $_.Exception.Message)
          $script:sel.TypeText([string]$t)
        }
        continue
      }
      default {
        if ($t -ne '') { $script:sel.Font.Bold = (ConvertTo-WordBool $b); $script:sel.Font.Italic = (ConvertTo-WordBool $i); $script:sel.TypeText($t) }
      }
    }
  }
  $script:sel.Font.Bold = (ConvertTo-WordBool $Bold); $script:sel.Font.Italic = (ConvertTo-WordBool $Italic)
}
function Complete-Para { $script:sel.TypeParagraph() }
function Add-TocEntry([string]$Entry, [int]$TocLevel) {
  # Hidden TC field; the TOC is built from these fields only, so entries hold headings, not body text.
  $clean = ($Entry -replace '"', "'")
  [int]$wasBold = $script:sel.Font.Bold
  if ($wasBold -ne 0 -and $wasBold -ne -1) { $wasBold = 0 }   # 9999999 = mixed
  $script:sel.Font.Bold = 0   # TOC style decides bold (L-012), not the heading run the field sits in
  $script:sel.Fields.Add($script:sel.Range, -1, ('TC "' + $clean + '" \l ' + $TocLevel), $false) | Out-Null
  $script:sel.Font.Bold = $wasBold
}
function Add-BottomRule([double]$Distance = 1) {
  # applies to the paragraph just ended; $Distance = points between the text and the rule (L-008a)
  $p = $script:doc.Paragraphs.Item($script:doc.Paragraphs.Count - 1)
  $bd = $p.Borders.Item($wdBorderBottom)
  $bd.LineStyle = 1; $bd.LineWidth = $RuleWidth
  Use-Format 'L-008a rule distance' { $p.Borders.DistanceFromBottom = [int][math]::Round($Distance) }   # Long in Word
}

try {
  $word = New-Object -ComObject Word.Application
  $word.Visible = $false
  $word.DisplayAlerts = 0
  $doc = $word.Documents.Add()
  $script:doc = $doc
  $script:sel = $word.Selection

  # ---------------- page setup (F-001, L-001) ----------------
  $ps = $doc.PageSetup
  $ps.TopMargin = $Margin; $ps.BottomMargin = $Margin; $ps.LeftMargin = $Margin; $ps.RightMargin = $Margin
  $ps.HeaderDistance = $HeaderDist; $ps.FooterDistance = $HeaderDist
  $ps.DifferentFirstPageHeaderFooter = -1
  $ps.OddAndEvenPagesHeaderFooter = -1
  $normal = $doc.Styles.Item(-1)   # wdStyleNormal
  $normal.Font.Name = $FontName; $normal.Font.Size = $FontSize
  $normal.ParagraphFormat.SpaceAfter = 0; $normal.ParagraphFormat.SpaceBefore = 0; $normal.ParagraphFormat.LineSpacingRule = 0

  # ---------------- front page header (F-012..F-023, L-005, L-007, L-008) ----------------
  Format-Para $wdAlignLeft 0 0 0
  $tbl = $doc.Tables.Add($sel.Range, 1, 2)
  $tbl.Borders.Enable = 0
  $tbl.Columns.Item(1).Width = $TextWidth / 2
  $tbl.Columns.Item(2).Width = $TextWidth / 2
  $tbl.LeftPadding = 0; $tbl.RightPadding = 0
  $c1 = $tbl.Cell(1, 1).Range
  $c1.Text = 'BY ORDER OF THE ' + [string](Get-Prop $meta 'byOrderOf')
  $byUnit = [string](Get-Prop $meta 'byOrderOfUnit')
  if ($byUnit) { $c1.InsertAfter("`r" + $byUnit) }
  $c1.Font.Bold = -1; $c1.Font.Italic = -1; $c1.ParagraphFormat.Alignment = $wdAlignLeft
  if ($shield) {   # checked above (L-007a)
    $tbl.Cell(1, 1).Range.InsertAfter("`r")
    $r = $tbl.Cell(1, 1).Range
    $r.MoveEnd(1, -1) | Out-Null   # exclude the end-of-cell mark
    $r.Collapse(0)
    $pic = $doc.InlineShapes.AddPicture((Resolve-Path -LiteralPath $shield).Path, $false, $true, $r)
    Use-Format 'L-007 seal aspect' { $pic.LockAspectRatio = 0 }   # msoFalse
    $pic.Width = [single]$ShieldWidth; $pic.Height = [single]$ShieldWidth   # square canvas: every seal fills the same 1.20 in box (L-007)
    Use-Format 'L-007 seal top' { $pic.Range.ParagraphFormat.SpaceBefore = [double]$SealBefore }
  }
  $right = New-Object System.Collections.Generic.List[object]
  $right.Add(@([string](Get-Prop $meta 'issuerLine'), 'bi'))
  $right.Add(@([string](Get-Prop $meta 'typeAndNumber'), 'bi'))
  $right.Add(@('', ''))
  $right.Add(@($dateText, 'bi'))
  foreach ($dl in @(Get-Prop $meta 'dateLines' | Where-Object { $null -ne $_ })) { $right.Add(@([string]$dl, 'i')) }
  $supLines = @(Get-Prop $meta 'supplementLines' | Where-Object { $null -ne $_ })
  if ($supLines.Count -gt 0) {                      # L-010c: organization / Supplement / supplement date group
    $right.Add(@('', ''))
    foreach ($sl in $supLines) { $right.Add(@([string]$sl, 'bi')) }
  }
  $right.Add(@('', ''))
  $right.Add(@([string](Get-Prop $meta 'seriesTitle'), 'bi'))
  $right.Add(@('', ''))
  $titleLines = @(Get-Prop $meta 'titleLines' | Where-Object { $null -ne $_ })
  if ($titleLines.Count -eq 0) { $titleLines = @([string](Get-Prop $meta 'title')) }
  foreach ($tl in $titleLines) { $right.Add(@(([string]$tl).ToUpper(), 'bi')) }   # F-018: all caps
  $c2 = $tbl.Cell(1, 2).Range
  $c2.Text = (($right | ForEach-Object { $_[0] }) -join "`r")
  $c2.ParagraphFormat.Alignment = $wdAlignRight
  for ($k = 0; $k -lt $right.Count; $k++) {
    $pr = $tbl.Cell(1, 2).Range.Paragraphs.Item($k + 1).Range
    $pr.Font.Bold = ConvertTo-WordBool ($right[$k][1] -like '*b*')
    $pr.Font.Italic = ConvertTo-WordBool ($right[$k][1] -like '*i*')
    if ($right[$k][0] -eq '') { Use-Format 'L-010c group line' { $pr.ParagraphFormat.LineSpacingRule = [int]$wdLineSpaceExactly; $pr.ParagraphFormat.LineSpacing = [single]$GroupBlankLine } }
  }
  $sel.EndKey($wdStory) | Out-Null

  Format-Para $wdAlignCenter 0 0 $ComplianceAfter
  Use-Format 'L-010e space before compliance' { $sel.ParagraphFormat.SpaceBefore = [single]$ComplianceBefore }   # about 0.42 in below the title or seal
  if ($directive) { Write-Rich 'COMPLIANCE WITH THIS PUBLICATION IS MANDATORY' $true }  # F-019 (4.5.4.7)
  Complete-Para; Add-BottomRule $ComplianceRuleDist

  Format-Para $wdAlignLeft $LabelTab (-$LabelTab) $SpaceAfter
  $sel.ParagraphFormat.TabStops.Add($LabelTab) | Out-Null
  Write-Rich 'ACCESSIBILITY:' $true; $sel.TypeText("`t")
  $accText = [string](Get-Prop $meta 'accessibility'); $accLink = Get-Prop $meta 'accessibilityLink'   # F-020
  $accStart = $sel.Range.Start
  Write-Rich $accText
  if ($null -ne $accLink) {
    # PFM 13 Nov: the wing site name in the statement links to the site's publications list (the PDF keeps the link).
    # The whole statement is typed first; the link text is then found in it and linked in place, so no text follows a link run.
    $linkText = [string](Get-Prop $accLink 'text')
    $find = $doc.Range($accStart, $sel.Range.Start)
    $find.Find.ClearFormatting(); $find.Find.MatchWildcards = $false
    if ($linkText -and $find.Find.Execute($linkText)) {
      $hl = $doc.Hyperlinks.Add($find, [string](Get-Prop $accLink 'url'), '', '', $linkText)
      # Match the DAFMAN 90-161 cover link (the e-Publishing address on its page 1): bold, pure blue, underlined (R03 PDF was theme teal, regular).
      $hl.Range.Font.Bold = -1; $hl.Range.Font.Color = 16711680; $hl.Range.Font.Underline = 1   # wdColorBlue, wdUnderlineSingle
      $sel.EndKey($wdStory) | Out-Null; $sel.Font.Reset()   # no Hyperlink style on the text that follows
    } else { $script:formatFails++; Write-Output 'FORMAT-FAIL F-020 accessibility link text not found in the statement' }
  }
  Complete-Para
  Format-Para $wdAlignLeft $LabelTab (-$LabelTab) $ReleaseAfter
  $sel.ParagraphFormat.TabStops.Add($LabelTab) | Out-Null
  Write-Rich 'RELEASABILITY:' $true; $sel.TypeText("`t"); Write-Rich ([string](Get-Prop $meta 'releasability')); Complete-Para; Add-BottomRule $ReleaseRuleDist

  # OPR / Certified by / Supersedes / Pages block (L-010f-h), as a borderless 2-column table:
  # row 1: OPR | Certified by;  row 2: | (certifier name);  row 3: Supersedes | Pages
  Format-Para $wdAlignLeft 0 0 0
  $sup = @(Get-Prop $meta 'supersedes' | Where-Object { $null -ne $_ })
  $ot = $doc.Tables.Add($sel.Range, 3, 2)
  $ot.Borders.Enable = 0
  $ot.LeftPadding = 0; $ot.RightPadding = 0
  $ot.Columns.Item(1).Width = $OprLeftCol
  $ot.Columns.Item(2).Width = $TextWidth - $OprLeftCol
  $ot.Range.Font.Name = $FontName; $ot.Range.Font.Size = $FontSize; $ot.Range.Font.Bold = 0; $ot.Range.Font.Italic = 0
  $ot.Range.ParagraphFormat.SpaceAfter = 0; $ot.Range.ParagraphFormat.SpaceBefore = 0
  $c = $ot.Cell(1, 1).Range; $c.Text = 'OPR:' + "`t" + [string](Get-Prop $meta 'opr')                           # F-021 (4.5.4.10)
  $c.ParagraphFormat.TabStops.ClearAll(); $c.ParagraphFormat.TabStops.Add($OprTab) | Out-Null
  $c = $ot.Cell(1, 2).Range; $c.Text = 'Certified by: ' + [string](Get-Prop $meta 'certifiedBy'); $c.ParagraphFormat.Alignment = $wdAlignRight   # "by" lower case (PFM, 2026-11-11)
  $c = $ot.Cell(2, 2).Range; $c.Text = '(' + ([string](Get-Prop $meta 'certifiedByName')).Trim('(', ')', ' ') + ')'; $c.ParagraphFormat.Alignment = $wdAlignRight   # certifier name line (PFM, 2026-11-11)
  if ($sup.Count -gt 0) {   # F-022 (4.5.4.12): line omitted when nothing is superseded
    $c = $ot.Cell(3, 1).Range
    $c.Text = 'Supersedes:' + "`t" + (($sup | ForEach-Object { [string](Get-Prop $_ 'designator') + ', ' + [string](Get-Prop $_ 'date') }) -join '; ')
    $c.ParagraphFormat.TabStops.ClearAll(); $c.ParagraphFormat.TabStops.Add($SupTab) | Out-Null
    $c.ParagraphFormat.LeftIndent = $SupTab; $c.ParagraphFormat.FirstLineIndent = -$SupTab
  }
  $c = $ot.Cell(3, 2).Range; $c.Text = 'Pages: 0'; $c.ParagraphFormat.Alignment = $wdAlignRight   # F-023; "0" replaced after layout
  $pc = $ot.Cell(3, 2).Range
  $doc.Bookmarks.Add('PagesCount', $doc.Range($pc.End - 2, $pc.End - 1)) | Out-Null
  $sel.EndKey($wdStory) | Out-Null
  Format-Para $wdAlignLeft 0 0 0
  Use-Format 'L-008a space before third rule' { $sel.ParagraphFormat.SpaceBefore = [single]$BlockRuleBefore }
  Complete-Para; Add-BottomRule

  # ---------------- opening paragraph (F-024, F-025) ----------------
  Format-Para $wdAlignJustify 0 0 0   # L-008a: blank line, no space after, then the opening paragraph
  Complete-Para
  Format-Para $wdAlignJustify 0 0 $SpaceAfter
  Write-Rich (Get-OpeningParagraph $pub); Complete-Para   # 4.5.5: fixed statements from code, slots from content

  # ---------------- summary of changes (F-026, 4.5.6) ----------------
  $soc = [string](Get-Prop $pub 'summaryOfChanges')
  if ($soc) {
    Format-Para $wdAlignLeft 0 0 $SpaceAfter $true
    Write-Rich 'SUMMARY OF CHANGES' $true $true; Complete-Para
    Format-Para $wdAlignJustify 0 0 $SpaceAfter
    Write-Rich $soc; Complete-Para
  }

  # ---------------- table of contents (F-027, 4.5.8.2-4.5.8.3) ----------------
  $wantToc = $true   # F-027: ANG wing publications always carry a TOC (4.5.8.2), built per 4.5.8.3 (PFM, 2026-11-11)
  $tocRange = $null
  if ($wantToc) {
    Format-Para $wdAlignLeft 0 0 0
    $tocRange = $sel.Range
    Complete-Para
  }

  # ---------------- body ----------------
  $body = Get-Prop $pub 'body'
  $chapters = @(Get-Prop $body 'chapters' | Where-Object { $null -ne $_ })
  $flat = @(Get-Prop $body 'paragraphs' | Where-Object { $null -ne $_ })
  $script:hasChapters = $chapters.Count -gt 0
  $script:tableCounter = @{}

  function Write-Paragraph($P, [string]$Number, [int]$Level, [string]$Unit) {
    # Level 1 = main paragraph (bold number and heading, F-028/F-033); deeper levels indent 0.25 in each (L-002), not bold (F-004).
    $indent = ($Level - 1) * $IndentStep
    $revised = [bool](Get-Prop $P 'revised')
    Format-Para $wdAlignJustify $indent 0 $SpaceAfter
    $isTop = ($Level -eq 1)
    Write-Rich $Number $isTop
    $t = [string](Get-Prop $P 'title')
    $x = [string](Get-Prop $P 'text')
    if ($t) { $sel.TypeText($Gap); Write-Rich $t $isTop }
    if ($isTop) { Add-TocEntry ($Number + "`t" + ($t -replace '\{/?[ib]\}', '')) 2 }   # TOC: main paragraph headings only (4.5.8.3); number at 1.50, text at 2.00 (L-012)
    if ($x) { $sel.TypeText($Gap); Write-Rich $x }
    foreach ($n in @(Get-Prop $P 'notes' | Where-Object { $null -ne $_ })) { $sel.TypeText($Gap); Write-Rich 'Note:' $true; $sel.TypeText(' '); Write-Rich ([string]$n) }        # F-037 (4.6.2)
    foreach ($e in @(Get-Prop $P 'exceptions' | Where-Object { $null -ne $_ })) { $sel.TypeText($Gap); Write-Rich 'Exception:' $true; $sel.TypeText(' '); Write-Rich ([string]$e) }  # F-037 (4.6.3)
    Complete-Para
    if ($revised) {   # F-026: manual margin bar as a left border for camera-ready ICs (4.5.6.2)
      $pp = $script:doc.Paragraphs.Item($script:doc.Paragraphs.Count - 1)
      $lb = $pp.Borders.Item($wdBorderLeft); $lb.LineStyle = 1; $lb.LineWidth = 6
    }
    foreach ($b in @(Get-Prop $P 'bullets' | Where-Object { $null -ne $_ })) {   # non-directive only (F-029)
      Format-Para $wdAlignJustify ($indent + $IndentStep) 0 $SpaceAfter
      $sel.Range.ListFormat.ApplyBulletDefault() | Out-Null
      Write-Rich ([string]$b); Complete-Para
      $sel.Range.ListFormat.RemoveNumbers() | Out-Null
    }
    $tbl = Get-Prop $P 'table'
    if ($null -ne $tbl) { Write-Table $tbl $Unit }
    $kids = @(Get-Prop $P 'children' | Where-Object { $null -ne $_ })
    for ($i = 0; $i -lt $kids.Count; $i++) { Write-Paragraph $kids[$i] ("$Number$($i + 1).") ($Level + 1) $Unit }
  }

  function Write-Table($T, [string]$Unit) {
    # F-038 (4.6.4): number and title directly above, bold (4.5.9.7.4.7); numbering per Table 4.1
    if (-not $script:tableCounter.ContainsKey($Unit)) { $script:tableCounter[$Unit] = 0 }
    $script:tableCounter[$Unit]++
    $num = $script:tableCounter[$Unit]
    if ($Unit -ne '') { $num = "$Unit.$num" }
    Format-Para $wdAlignLeft 0 0 0 $true
    Write-Rich ("Table $num." + $Gap + [string](Get-Prop $T 'title')) $true; Complete-Para
    $cols = @(Get-Prop $T 'columns'); $rows = @(Get-Prop $T 'rows')
    Format-Para $wdAlignLeft 0 0 0
    $wt = $script:doc.Tables.Add($script:sel.Range, $rows.Count + 1, $cols.Count)
    $wt.Borders.Enable = 1
    for ($c = 0; $c -lt $cols.Count; $c++) { $wt.Cell(1, $c + 1).Range.Text = (([string]$cols[$c]) -replace '\{/?[ib]\}', '') }
    for ($r = 0; $r -lt $rows.Count; $r++) {
      $cells = @($rows[$r])
      for ($c = 0; $c -lt $cols.Count; $c++) { $wt.Cell($r + 2, $c + 1).Range.Text = (([string]$cells[$c]) -replace '\{/?[ib]\}', '') }
    }
    $wt.Range.Font.Name = $FontName; $wt.Range.Font.Size = $FontSize
    $wt.Range.ParagraphFormat.SpaceAfter = 0
    $script:sel.EndKey($wdStory) | Out-Null
    Format-Para $wdAlignLeft 0 0 $SpaceAfter; Complete-Para
  }

  if ($script:hasChapters) {
    for ($c = 0; $c -lt $chapters.Count; $c++) {
      $ch = $chapters[$c]; $cn = $c + 1
      $sel.InsertBreak($wdPageBreak)                       # L-009: each chapter starts a new page
      Format-Para $wdAlignCenter 0 0 $SpaceAfter $true
      Write-Rich ("Chapter $cn") $true
      Add-TocEntry ("Chapter $cn$EmDash" + ([string](Get-Prop $ch 'title')).ToUpper()) 1
      Complete-Para           # F-033 (4.5.9.7.4.4)
      Format-Para $wdAlignCenter 0 0 ($SpaceAfter * 2) $true
      Write-Rich ([string](Get-Prop $ch 'title')).ToUpper() $true; Complete-Para   # F-033 (4.5.9.7.4.5)
      $ps2 = @(Get-Prop $ch 'paragraphs' | Where-Object { $null -ne $_ })
      for ($i = 0; $i -lt $ps2.Count; $i++) { Write-Paragraph $ps2[$i] ("$cn.$($i + 1).") 1 "$cn" }
    }
  } else {
    for ($i = 0; $i -lt $flat.Count; $i++) { Write-Paragraph $flat[$i] ("$($i + 1).") 1 '' }
  }

  # ---------------- approving official (F-034, 4.5.10, L-006) ----------------
  $sig = @(Get-Prop $pub 'signature' | Where-Object { $null -ne $_ })
  if ($sig.Count -gt 0) {
    Format-Para $wdAlignLeft 0 0 0; Complete-Para; Complete-Para
    for ($s = 0; $s -lt $sig.Count; $s++) {
      Format-Para $wdAlignLeft $SigIndent 0 0
      $line = [string]$sig[$s]
      if ($s -eq 0) { $line = $line.ToUpper() }
      Write-Rich $line; Complete-Para
    }
  }

  # ---------------- attachments (F-035, F-036, 4.5.11) ----------------
  $atts = @(Get-Prop $pub 'attachments' | Where-Object { $null -ne $_ })
  for ($a = 0; $a -lt $atts.Count; $a++) {
    $at = $atts[$a]; $an = $a + 1
    $sel.InsertBreak($wdPageBreak)
    Format-Para $wdAlignCenter 0 0 $SpaceAfter $true
    Write-Rich "Attachment $an" $true
    Add-TocEntry ("Attachment $an$EmDash" + ([string](Get-Prop $at 'title')).ToUpper()) 1
    Complete-Para
    Format-Para $wdAlignCenter 0 0 ($SpaceAfter * 2) $true
    Write-Rich ([string](Get-Prop $at 'title')).ToUpper() $true; Complete-Para
    $g = Get-Prop $at 'glossary'
    if ($null -ne $g) {
      $sections = @(
        @('References', 'references', 'list'),
        @('Prescribed Forms', 'prescribedForms', 'list'),
        @('Adopted Forms', 'adoptedForms', 'list'),
        @('Abbreviations and Acronyms', 'abbreviations', 'pairs'),
        @('Office Symbols', 'officeSymbols', 'pairs'),
        @('Terms', 'terms', 'pairs'))
      foreach ($sec in $sections) {
        Format-Para $wdAlignLeft 0 0 $SpaceAfter $true
        Write-Rich $sec[0] $true; Complete-Para                    # 4.5.9.7.4.14.1: category titles bold
        $items = @(Get-Prop $g $sec[1] | Where-Object { $null -ne $_ })
        if ($items.Count -eq 0) {
          if ($sec[1] -in @('prescribedForms', 'adoptedForms')) { Format-Para $wdAlignLeft 0 0 $SpaceAfter; Write-Rich 'None'; Complete-Para }
          continue
        }
        foreach ($it in $items) {
          Format-Para $wdAlignLeft 0 0 $SpaceAfter
          if ($sec[2] -eq 'list') { Write-Rich ([string]$it) }
          else {
            Write-Rich ([string](Get-Prop $it 'term')) $true  # 4.5.9.7.4.14.2-3: terms bold, definitions not
            $sel.TypeText($EmDash); Write-Rich ([string](Get-Prop $it 'definition'))
          }
          Complete-Para
        }
      }
    } else {
      $aps = @(Get-Prop $at 'paragraphs' | Where-Object { $null -ne $_ })
      for ($i = 0; $i -lt $aps.Count; $i++) { Write-Paragraph $aps[$i] ("A$an.$($i + 1).") 1 "A$an" }
    }
  }

  # ---------------- running headers (L-001, F-010) ----------------
  $sec1 = $doc.Sections.Item(1)
  $runText = $designator + $Gap + $dateText.ToUpper()
  if ($dateText -eq '(Date)') { $runText = $designator + $Gap + $dateText }
  foreach ($kind in @($wdHeaderFirst, $wdHeaderPrimary, $wdHeaderEven)) {
    $h = $sec1.Headers.Item($kind).Range
    $h.Text = ''
    $h.Font.Name = $FontName; $h.Font.Size = $FontSize; $h.Font.Bold = -1
    $h.ParagraphFormat.TabStops.ClearAll()
    $h.ParagraphFormat.TabStops.Add($TextWidth, $wdAlignTabRight) | Out-Null
    if ($Mode -eq 'draft') {
      $h.InsertAfter($DraftMark); $h.ParagraphFormat.Alignment = $wdAlignCenter
      if ($kind -ne $wdHeaderFirst) { $h.InsertParagraphAfter() }
    }
    if ($kind -eq $wdHeaderFirst) { continue }   # cover page has no running header
    $line = $sec1.Headers.Item($kind).Range.Paragraphs.Last.Range
    $line.ParagraphFormat.Alignment = $wdAlignLeft
    if ($kind -eq $wdHeaderPrimary) {             # odd pages: designator left, page number right
      $line.InsertAfter($runText + "`t")
      $end = $sec1.Headers.Item($kind).Range
      $end.MoveEnd(1, -1) | Out-Null   # exclude the final paragraph mark
      $end.Collapse(0)
      $end.Fields.Add($end, $wdFieldPage) | Out-Null
    } else {                                      # even pages: page number left, designator right
      $start = $line.Duplicate; $start.Collapse(1)
      $start.Fields.Add($start, $wdFieldPage) | Out-Null
      $sec1.Headers.Item($kind).Range.InsertAfter("`t" + $runText)
    }
  }

  # ---------------- TOC and page count ----------------
  if ($null -ne $tocRange) {
    Format-Para $wdAlignLeft 0 0 0
    foreach ($lv in @(@($wdStyleTOC1, $true, 0), @($wdStyleTOC2, $false, $TocNumber))) {   # L-012
      [int]$styleId = $lv[0]; [bool]$styleBold = $lv[1]; [single]$styleFirst = $lv[2] - $TocHang
      Use-Format ('L-012 TOC font ' + $styleId) {
        $st = $doc.Styles.Item($styleId)
        $st.Font.Name = [string]$FontName; $st.Font.Size = [single]$TocFontSize
        $st.Font.Bold = [int](ConvertTo-WordBool $styleBold); $st.Font.Italic = 0
      }
      # Gov runs 2026-11-11 (6 of 6): setting $st.ParagraphFormat.LeftIndent threw "Specified cast is not valid".
      # Try 3 routes and print the one that works: direct, a copied ParagraphFormat assigned back, late-bound InvokeMember.
      $tocPf = [ordered]@{ LeftIndent = [double]$TocHang; FirstLineIndent = [double]$styleFirst; SpaceBefore = [double]0
                           SpaceAfter = [double]$TocAfter; LineSpacingRule = [int]$wdLineSpaceExactly; LineSpacing = [double]$TocLine }
      Use-Format ('L-012 TOC indent ' + $styleId) {
        $st = $doc.Styles.Item($styleId)
        $route = Invoke-ParaFormat $st $tocPf
        $got = $doc.Styles.Item($styleId).ParagraphFormat   # read back: a route that reports success must also take effect
        Write-Output ('L-012 TOC indent ' + $styleId + ' route=' + $route + ' left=' + $got.LeftIndent + ' first=' + $got.FirstLineIndent + ' (want ' + $tocPf.LeftIndent + ' / ' + $tocPf.FirstLineIndent + ')')
      }
    }
    $doc.TablesOfContents.Add($tocRange, $false, 1, 2, $true, '', $true, $true, '', $true, $true, $false) | Out-Null   # UseFields = TC entries only
    $doc.TablesOfContents.Item(1).Update()
  }
  $doc.Repaginate()
  $pages = $doc.ComputeStatistics($wdStatisticPages)
  $doc.Bookmarks.Item('PagesCount').Range.Text = [string]$pages
  $doc.Fields.Update() | Out-Null

  # ---------------- self-measure (Stage 1, PFM 1A): Word read-back against the DAFMAN values, PASS/FAIL per line ----------------
  # Vertical positions from Range.Information(6) (points from the page top). Values: L-007 seal top 1.47 in;
  # L-012 TOC line pitch 0.272 in (docs/format-rules.md). Tolerance 0.03 in (0.01 in for pitch).
  try {
    try { $doc.ActiveWindow.View.Type = 3 } catch { Write-Output ('MEASURE-ERROR print layout view: ' + $_.Exception.Message) }   # wdPrintView: Information() needs layout
    $measure = {
      param([string]$What, [double]$GotPt, [double]$WantIn, [double]$TolIn)
      if ($GotPt -lt 0) { return ('MEASURE-ERROR ' + $What + ' not laid out (Information returned ' + $GotPt + ')') }
      $gotIn = [math]::Round($GotPt / 72, 3)
      $verdict = 'FAIL'
      if ([math]::Abs($gotIn - $WantIn) -le $TolIn) { $verdict = 'PASS' }
      'MEASURE ' + $What + ' got=' + $gotIn + 'in want=' + $WantIn + 'in tol=' + $TolIn + ' ' + $verdict
    }
    if ($shield) {
      if ($pic) { $sealAt = $pic.Range.Duplicate; $sealAt.Collapse(1); Write-Output (& $measure 'L-007 seal top' ([double]$sealAt.Information(6)) 1.47 0.03) }
      else { Write-Output 'MEASURE-ERROR L-007 seal top not measured: no picture' }
    }
    if ($null -ne $tocRange -and $doc.TablesOfContents.Count -ge 1) {
      $tocAll = @(); foreach ($tp in $doc.TablesOfContents.Item(1).Range.Paragraphs) { $tocAll += $tp }
      # L-012 horizontal positions (number 1.50 in, text 2.00 in) are measured on the returned PDF (scripts/measure_pdf.py):
      # R01 and R02 showed Range.Information(5) reads TOC 2 lines 0.50 in short while the PDF is right (docs/reviews/2026-11-13-r02-results.md).
      $pitchDone = $false
      # Pitch between entries: the first one-line entry and the entry after it (a wrapped entry adds 0.202 in per line).
      for ($k = 0; $k -lt $tocAll.Count - 1; $k++) {
        $s1 = $tocAll[$k].Range.Duplicate; $s1.Collapse(1)
        $e1 = $tocAll[$k].Range.Duplicate; $e1.MoveEnd(1, -1) | Out-Null; $e1.Collapse(0)
        if ([math]::Abs([double]$e1.Information(6) - [double]$s1.Information(6)) -lt 1) {
          $s2 = $tocAll[$k + 1].Range.Duplicate; $s2.Collapse(1)
          Write-Output (& $measure 'L-012 TOC pitch' ([double]$s2.Information(6) - [double]$s1.Information(6)) 0.272 0.01)
          $pitchDone = $true; break
        }
      }
      if (-not $pitchDone) { Write-Output 'MEASURE-ERROR L-012 TOC pitch not measured: no one-line entry followed by another' }
    }
  } catch { Write-Output ('MEASURE-ERROR ' + $_.Exception.Message) }

  # ---------------- sensitivity label (PFM 13 Nov): apply the label captured once from a hand-labeled file ----------------
  # Config\90161Z-label.json (written by 90161Z-T13-label-capture-r2.ps1, kept only on this computer) holds the label and
  # tenant ids; they are never printed. Lowering a label needs a justification (Office VBA LabelInfo.Justification).
  $labelCfg = Join-Path (Split-Path -Parent $PSScriptRoot) 'Config\90161Z-label.json'
  if (Test-Path -LiteralPath $labelCfg -PathType Leaf) {
    try {
      try { $cfg = Get-Content -LiteralPath $labelCfg -Raw | ConvertFrom-Json }
      catch { throw 'Config\90161Z-label.json cannot be read; run the label capture step again' }   # fixed text: never echo the file
      $sl = $doc.SensitivityLabel
      $li = $sl.CreateLabelInfo()
      $li.LabelId = [string]$cfg.labelId; $li.SiteId = [string]$cfg.siteId; $li.LabelName = [string]$cfg.labelName
      $li.AssignmentMethod = 1   # PRIVILEGED: chosen, as when a person picks it
      $li.SetDate = Get-Date
      $li.Justification = 'Generated by the 90-161.Z renderer from fake or approved content; label set to the captured default.'
      $ctx = New-Object -ComObject Scripting.Dictionary
      $sl.SetLabel($li, $ctx)
      $got = $sl.GetLabel()
      # Word often reads LabelName back empty (R02); the id match is the check.
      if ([string]$got.LabelId -eq [string]$cfg.labelId) { Write-Output 'LABEL applied (label id matches the captured label) PASS' }
      else { Write-Output ('LABEL FAIL read back name=' + $got.LabelName + ' (want ' + $cfg.labelName + ')') }
    } catch { Write-Output ('LABEL FAIL ' + $_.Exception.Message) }
  } else { Write-Output 'LABEL not set: no Config\90161Z-label.json yet (run the label capture step once)' }

  # Join-Path returns a PSObject-wrapped string; Word COM rejects it by ref (gov run 2026-11-11). Pass plain typed values.
  [string]$saveName = [string]$outDocx
  [int]$saveFormat = $wdFormatDocx
  $doc.SaveAs([ref]$saveName, [ref]$saveFormat)
  Write-Output ("RENDER docx=" + (Split-Path -Leaf $outDocx) + " pages=$pages mode=$Mode toc=$([bool]$tocRange)")
  if ($Pdf) {
    $outPdf = [IO.Path]::ChangeExtension($outDocx, '.pdf')
    $doc.ExportAsFixedFormat([string]$outPdf, [int]$wdFormatPdf)
    Write-Output ("RENDER pdf=" + (Split-Path -Leaf $outPdf))
  }
} catch {
  # Name the line, so a gov-device result shows where Word stopped.
  Write-Output ('RENDER-ERROR line ' + $_.InvocationInfo.ScriptLineNumber + ': ' + ([string]$_.InvocationInfo.Line).Trim() + ' :: ' + $_.Exception.Message)
  throw
} finally {
  # Each cleanup step on its own, so a cleanup error never hides the real one or leaves WINWORD.EXE running.
  [int]$noSave = 0
  if ($doc) { try { $doc.Close([ref]$noSave) } catch { Write-Output ('CLEANUP close: ' + $_.Exception.Message) } }
  if ($word) {
    try { $word.Quit() } catch { Write-Output ('CLEANUP quit: ' + $_.Exception.Message) }
    try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($word) } catch { Write-Output ('CLEANUP release: ' + $_.Exception.Message) }
  }
}
if ($script:formatFails -gt 0) { Write-Output ('FORMAT-FAILS count=' + $script:formatFails); exit 3 }
'@ }
